local _system_hex = ""

-- Sử dụng string.gsub xử lý trực tiếp bằng lõi C của Executor, không gây lag máy
local _success, _source = pcall(function()
    return (string.gsub(_system_hex, "..", function(_char)
        return string.char(tonumber(_char, 16))
    end))
end)

if _success and _source then
    local _run, _err = loadstring(_source)
    if _run then
        -- Kích hoạt quyền môi trường tối cao để gọi thư viện UI (Fluent/Rayfield/RedZ)
        setfenv(_run, getfenv())()
    else
        warn("❌ Lỗi biên dịch mã nguồn: " .. tostring(_err))
    end
else
    warn("❌ Lỗi giải mã hệ thống Hyper Engine!")
end
